<?php
require_once __DIR__.'/../includes/bootstrap.php'; require_admin();
$title='Customer Members'; $msg=''; $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';$id=(int)($_POST['customer_id']??0);
 if($action==='save'){$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$username=trim($_POST['username']??'');$status=in_array($_POST['status']??'', ['ACTIVE','INACTIVE'], true)?$_POST['status']:'ACTIVE';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[A-Za-z0-9._-]{3,50}$/',$username))$errors[]='Enter valid name, email and username.';else{$q=$pdo->prepare('SELECT customer_id FROM customers WHERE (LOWER(email)=LOWER(?) OR username=?) AND customer_id<>? LIMIT 1');$q->execute([$email,$username,$id]);if($q->fetch())$errors[]='Email or username already belongs to another customer.';else{$pdo->prepare('UPDATE customers SET full_name=?,email=?,phone=?,username=?,status=? WHERE customer_id=?')->execute([$name,$email,$phone,$username,$status,$id]);$msg='Customer details updated.';}}}
 elseif($action==='add'){$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$username=trim($_POST['username']??'');$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[A-Za-z0-9._-]{3,50}$/',$username)||strlen($pass)<8)$errors[]='Complete all required registration fields; password must be at least 8 characters.';else{$q=$pdo->prepare('SELECT customer_id FROM customers WHERE LOWER(email)=LOWER(?) OR username=? LIMIT 1');$q->execute([$email,$username]);if($q->fetch())$errors[]='Email or username already exists.';else{$pdo->prepare("INSERT INTO customers(username,password_hash,full_name,email,phone,status,email_verified) VALUES(?,?,?,?,?,'ACTIVE',0)")->execute([$username,password_hash($pass,PASSWORD_DEFAULT),$name,$email,$phone]);$msg='New customer account created.';}}}
 elseif($action==='delete' && $id){if($id===(int)($_SESSION['customer_id']??0))$errors[]='A management account cannot delete itself from this page.';else{try{$pdo->beginTransaction();$pdo->prepare('DELETE FROM customer_private_messages WHERE customer_id=?')->execute([$id]);$pdo->prepare('DELETE FROM customer_messages WHERE customer_id=?')->execute([$id]);$pdo->prepare('DELETE FROM wishlists WHERE customer_id=?')->execute([$id]);$pdo->prepare('DELETE FROM recently_viewed WHERE customer_id=?')->execute([$id]);$pdo->prepare('DELETE FROM seller_follows WHERE customer_id=?')->execute([$id]);$pdo->prepare('DELETE FROM product_reviews WHERE customer_id=?')->execute([$id]);$pdo->prepare('DELETE FROM password_reset_otps WHERE customer_id=?')->execute([$id]);$pdo->prepare('DELETE FROM order_status_history WHERE order_id IN (SELECT order_id FROM orders WHERE customer_id=?)')->execute([$id]);$pdo->prepare('DELETE FROM order_items WHERE order_id IN (SELECT order_id FROM orders WHERE customer_id=?)')->execute([$id]);$pdo->prepare('DELETE FROM orders WHERE customer_id=?')->execute([$id]);$pdo->prepare('DELETE FROM customers WHERE customer_id=?')->execute([$id]);$pdo->commit();$msg='Customer and associated account data permanently deleted.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='The customer could not be deleted completely. Check database constraints before retrying.';}}}
}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM customers WHERE customer_id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}
$rows=$pdo->query("SELECT c.*, (SELECT COUNT(*) FROM orders o WHERE o.customer_id=c.customer_id) order_count, (SELECT COUNT(*) FROM customer_private_messages pm WHERE pm.customer_id=c.customer_id AND pm.sender_type='CUSTOMER' AND pm.is_read=0) unread FROM customers c ORDER BY c.created_at DESC")->fetchAll();
require __DIR__.'/../includes/header.php';?><div class="admin-layout"><aside class="admin-side"><strong>Management</strong><a href="/admin/dashboard.php">Dashboard</a><a href="/admin/products.php">Products</a><a href="/admin/orders.php">Orders</a><a class="active" href="/admin/customers.php">Members</a><a href="/admin/messages.php">Private chat</a><a href="/admin/reviews.php">Comments & reviews</a><?php if(super_admin()): ?><a href="/admin/users.php">Admin accounts</a><?php endif; ?><a href="/">View store</a></aside><section class="admin-main"><div class="section-head"><div><span class="eyebrow">CUSTOMER DATABASE CONTROL</span><h1>Registered members</h1><p>View, edit, disable, permanently delete, create and privately contact customer accounts.</p></div><a class="btn primary" href="#add-member">+ Add customer</a></div><?php foreach($errors as $x): ?><div class="errors"><?=e($x)?></div><?php endforeach; ?><?php if($msg): ?><div class="flash success"><?=e($msg)?></div><?php endif; ?>
<div class="panel" id="add-member"><h2><?= $edit?'Edit customer':'Add customer from management' ?></h2><form method="post" class="form"><input type="hidden" name="action" value="<?=$edit?'save':'add'?>"><input type="hidden" name="customer_id" value="<?=$edit['customer_id']??0?>"><?=csrf_field()?><div class="two"><label>Full name<input name="full_name" required value="<?=e($edit['full_name']??'')?>"></label><label>Username<input name="username" required minlength="3" maxlength="50" value="<?=e($edit['username']??'')?>"></label></div><div class="two"><label>Email<input type="email" name="email" required value="<?=e($edit['email']??'')?>"></label><label>Phone<input name="phone" value="<?=e($edit['phone']??'')?>"></label></div><?php if(!$edit): ?><label>Password<input type="password" name="password" required minlength="8"><small>Use the same registration password requirement.</small></label><?php else: ?><label>Status<select name="status"><option <?=$edit['status']==='ACTIVE'?'selected':''?>>ACTIVE</option><option <?=$edit['status']==='INACTIVE'?'selected':''?>>INACTIVE</option></select></label><?php endif; ?><button class="btn primary"><?=$edit?'Save customer changes':'Create customer account'?></button><?php if($edit): ?><a class="btn ghost" href="/admin/customers.php">Cancel edit</a><?php endif; ?></form></div>
<div class="table-wrap"><table><thead><tr><th>Member</th><th>Contact</th><th>Orders</th><th>Status</th><th>Last seen</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['full_name'])?></strong><small>@<?=e($r['username'])?></small></td><td><?=e($r['email'])?><small><?=e($r['phone']??'')?></small></td><td><?=$r['order_count']?></td><td><span class="status-pill <?=strtolower($r['status'])==='active'?'status-delivered':'status-cancelled'?>"><?=e($r['status'])?></span></td><td><?=($r['last_seen_at']&&strtotime($r['last_seen_at'])>=time()-300)?'Online now':e($r['last_seen_at']??'Never')?></td><td><div class="admin-product-actions"><a class="btn small" href="/admin/customers.php?edit=<?=$r['customer_id']?>">Edit</a><a class="btn small" href="/admin/messages.php?customer_id=<?=$r['customer_id']?>">Chat<?php if((int)$r['unread']): ?> (<?=$r['unread']?>)<?php endif; ?></a><form method="post" onsubmit="return confirm('Permanently delete this customer and their stored account data? This also removes their orders, reviews and private messages.')"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="customer_id" value="<?=$r['customer_id']?>"><input type="hidden" name="full_name" value="<?=e($r['full_name'])?>"><input type="hidden" name="email" value="<?=e($r['email'])?>"><input type="hidden" name="username" value="<?=e($r['username'])?>"><input type="hidden" name="phone" value="<?=e($r['phone']??'')?>"><input type="hidden" name="status" value="<?=$r['status']==='ACTIVE'?'INACTIVE':'ACTIVE'?>"><button class="btn small"><?=$r['status']==='ACTIVE'?'Disable':'Enable'?></button></form><form method="post" onsubmit="return confirm('PERMANENT DELETE: continue?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="customer_id" value="<?=$r['customer_id']?>"><button class="link-danger">Delete permanently</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section></div><?php require __DIR__.'/../includes/footer.php'; ?>